#!/usr/bin/env tsx
/**
 * ADR-0008: rebuild the whole chunk layer from `articles` and `live_posts`.
 *
 * Wipes `chunks` and rebuilds every article's span or live-post chunks inside
 * one transaction (ArticleDb.rebuildAllChunks), then optimizes the FTS5
 * index. Safe to run any time, and safe to re-run repeatedly, because chunk
 * refs are deterministic (ADR-0004): a rebuild reproduces the exact same
 * chunk_ref set byte-for-byte, it never mints new identities.
 *
 * Usage: npx tsx scripts/rebuild-chunks.ts [outputDir]
 */

import { OUTPUT_DIR } from '../src/cli/config.js';
import { ArticleDb } from '../src/db.js';

export function rebuildChunks(outputDir: string): { articlesProcessed: number; chunksBuilt: number; liveUpdateArticles: number; durationMs: number } {
  const db = new ArticleDb(outputDir);
  try {
    const startedAt = Date.now();
    const stats = db.rebuildAllChunks();
    return { ...stats, durationMs: Date.now() - startedAt };
  } finally {
    db.close();
  }
}

function main(): void {
  const outputDir = process.argv[2] ?? OUTPUT_DIR;
  const stats = rebuildChunks(outputDir);
  console.log(
    `rebuild-chunks: ${stats.articlesProcessed} article(s) processed ` +
    `(${stats.liveUpdateArticles} live-update), ${stats.chunksBuilt} chunk(s) built ` +
    `in ${(stats.durationMs / 1000).toFixed(1)}s`,
  );
}

